import java.util.ArrayDeque;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

public class Solution {
    /** Lançada quando nenhuma conexão fica livre dentro do prazo de espera. */
    static final class PoolTimeoutException extends RuntimeException {
        PoolTimeoutException(String mensagem) {
            super(mensagem);
        }
    }

    static final class Pool<T> {
        private static final class Meta {
            final long criadaEm;
            long ultimoUso;
            boolean emUso;

            Meta(long criadaEm) {
                this.criadaEm = criadaEm;
                this.ultimoUso = criadaEm;
            }
        }

        private final int maxSize;
        private final long maxLifetimeMs;
        private final long idleTimeoutMs;
        private final Supplier<T> criar;
        private final Consumer<T> fechar;
        private final LongSupplier relogio;

        private final ReentrantLock lock = new ReentrantLock();
        private final Condition liberou = lock.newCondition();
        private final IdentityHashMap<T, Meta> todas = new IdentityHashMap<>();
        private final ArrayDeque<T> ociosas = new ArrayDeque<>();   // topo = devolvida mais recentemente
        private long criadas = 0;
        private long descartadas = 0;

        Pool(int maxSize, long maxLifetimeMs, long idleTimeoutMs, Supplier<T> criar, Consumer<T> fechar, LongSupplier relogio) {
            if (maxSize < 1) throw new IllegalArgumentException("maxSize precisa ser >= 1");
            if (maxLifetimeMs < 0 || idleTimeoutMs < 0) throw new IllegalArgumentException("limites negativos");
            if (criar == null || fechar == null || relogio == null) throw new IllegalArgumentException("argumento nulo");
            this.maxSize = maxSize;
            this.maxLifetimeMs = maxLifetimeMs;
            this.idleTimeoutMs = idleTimeoutMs;
            this.criar = criar;
            this.fechar = fechar;
            this.relogio = relogio;
        }

        T emprestar(long timeoutMs) throws InterruptedException {
            if (timeoutMs < 0) throw new IllegalArgumentException("timeout negativo");
            long restante = TimeUnit.MILLISECONDS.toNanos(timeoutMs);
            lock.lockInterruptibly();
            try {
                while (true) {
                    T c = tirarOciosaValida();
                    if (c == null && todas.size() < maxSize) {
                        c = criar.get();                                   // se lançar, nada foi registrado
                        todas.put(c, new Meta(relogio.getAsLong()));
                        criadas++;
                    }
                    if (c != null) {
                        todas.get(c).emUso = true;
                        return c;
                    }
                    if (restante <= 0) throw new PoolTimeoutException("nenhuma conexão livre em " + timeoutMs + " ms");
                    restante = liberou.awaitNanos(restante);
                }
            } finally {
                lock.unlock();
            }
        }

        void devolver(T conexao) {
            lock.lock();
            try {
                Meta m = todas.get(conexao);
                if (m == null) throw new IllegalArgumentException("conexão desconhecida");
                if (!m.emUso) throw new IllegalStateException("conexão já devolvida");
                m.emUso = false;
                long agora = relogio.getAsLong();
                if (venceuPorVida(m, agora)) {
                    descartar(conexao);
                } else {
                    m.ultimoUso = agora;
                    ociosas.addFirst(conexao);
                }
                liberou.signal();
            } finally {
                lock.unlock();
            }
        }

        int podarOciosas() {
            lock.lock();
            try {
                long agora = relogio.getAsLong();
                int fechadas = 0;
                for (Iterator<T> it = ociosas.iterator(); it.hasNext(); ) {
                    T c = it.next();
                    if (venceu(todas.get(c), agora)) {
                        it.remove();
                        descartar(c);
                        fechadas++;
                    }
                }
                return fechadas;
            } finally {
                lock.unlock();
            }
        }

        int abertas() { return locked(() -> todas.size()); }
        int emUso() { return locked(() -> todas.size() - ociosas.size()); }
        int ociosas() { return locked(() -> ociosas.size()); }
        long criadasNoTotal() { return locked(() -> criadas); }
        long descartadasNoTotal() { return locked(() -> descartadas); }

        // ---------- internos (sempre com o lock) ----------

        private T tirarOciosaValida() {
            long agora = relogio.getAsLong();
            while (!ociosas.isEmpty()) {
                T c = ociosas.pollFirst();
                if (venceu(todas.get(c), agora)) {
                    descartar(c);
                    continue;
                }
                return c;
            }
            return null;
        }

        private boolean venceuPorVida(Meta m, long agora) {
            return maxLifetimeMs > 0 && agora - m.criadaEm >= maxLifetimeMs;
        }

        private boolean venceu(Meta m, long agora) {
            return venceuPorVida(m, agora) || (idleTimeoutMs > 0 && agora - m.ultimoUso >= idleTimeoutMs);
        }

        private void descartar(T c) {
            todas.remove(c);
            descartadas++;
            fechar.accept(c);
        }

        private <R> R locked(Supplier<R> leitura) {
            lock.lock();
            try {
                return leitura.get();
            } finally {
                lock.unlock();
            }
        }
    }
}

