import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.LongSupplier;

class SolutionTest {
    static final class Relogio implements LongSupplier {
        long agora = 0;
        @Override public long getAsLong() { return agora; }
        Relogio em(long t) { agora = t; return this; }
    }

    static final class Conn {
        final int id;
        Conn(int id) { this.id = id; }
        @Override public String toString() { return "Conn#" + id; }
    }

    /** Fábrica de teste: numera as conexões e registra as fechadas. */
    static final class Fabrica {
        final AtomicInteger criadas = new AtomicInteger();
        final List<Conn> fechadas = Collections.synchronizedList(new ArrayList<>());
        Conn criar() { return new Conn(criadas.incrementAndGet()); }
        void fechar(Conn c) { fechadas.add(c); }
    }

    static Solution.Pool<Conn> pool(int max, long vida, long ocioso, Fabrica f, Relogio t) {
        return new Solution.Pool<>(max, vida, ocioso, f::criar, f::fechar, t);
    }

    // ---------- criação e reuso ----------

    @Test void criacaoEPreguicosa() throws Exception {
        Fabrica f = new Fabrica();
        Solution.Pool<Conn> p = pool(3, 0, 0, f, new Relogio());
        assertEquals(0, f.criadas.get());
        assertEquals(0, p.abertas());
        Conn c = p.emprestar(0);
        assertEquals(1, f.criadas.get());
        assertEquals(1, p.abertas());
        assertEquals(1, p.emUso());
        assertEquals(0, p.ociosas());
        assertNotNull(c);
    }

    @Test void conexaoDevolvidaEReaproveitada() throws Exception {
        Fabrica f = new Fabrica();
        Solution.Pool<Conn> p = pool(3, 0, 0, f, new Relogio());
        Conn a = p.emprestar(0);
        p.devolver(a);
        assertEquals(1, p.ociosas());
        assertSame(a, p.emprestar(0));
        assertEquals(1, f.criadas.get());
        assertEquals(1, p.criadasNoTotal());
    }

    @Test void reusoEmLifo() throws Exception {
        Fabrica f = new Fabrica();
        Solution.Pool<Conn> p = pool(3, 0, 0, f, new Relogio());
        Conn a = p.emprestar(0);
        Conn b = p.emprestar(0);
        p.devolver(a);
        p.devolver(b);
        assertSame(b, p.emprestar(0), "a devolvida mais recentemente sai primeiro");
        assertSame(a, p.emprestar(0));
    }

    // ---------- limite e espera ----------

    @Test void nuncaPassaDoMaximo() throws Exception {
        Fabrica f = new Fabrica();
        Solution.Pool<Conn> p = pool(2, 0, 0, f, new Relogio());
        p.emprestar(0);
        p.emprestar(0);
        assertThrows(Solution.PoolTimeoutException.class, () -> p.emprestar(0));
        assertEquals(2, p.abertas());
        assertEquals(2, f.criadas.get());
    }

    @Test void timeoutReal() throws Exception {
        Fabrica f = new Fabrica();
        Solution.Pool<Conn> p = pool(1, 0, 0, f, new Relogio());
        p.emprestar(0);
        long ini = System.nanoTime();
        assertThrows(Solution.PoolTimeoutException.class, () -> p.emprestar(40));
        long ms = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - ini);
        assertTrue(ms >= 35, "esperou o prazo antes de desistir: " + ms + " ms");
        assertEquals(1, p.emUso());
    }

    @Test void devolucaoAcordaQuemEspera() throws Exception {
        Fabrica f = new Fabrica();
        Solution.Pool<Conn> p = pool(1, 0, 0, f, new Relogio());
        Conn a = p.emprestar(0);
        AtomicReference<Conn> recebida = new AtomicReference<>();
        CountDownLatch vaiPedir = new CountDownLatch(1);
        Thread espera = new Thread(() -> {
            try {
                vaiPedir.countDown();
                recebida.set(p.emprestar(5000));
            } catch (Exception e) {
                recebida.set(null);
            }
        });
        espera.start();
        assertTrue(vaiPedir.await(2, TimeUnit.SECONDS));
        p.devolver(a);
        espera.join(3000);
        assertFalse(espera.isAlive(), "quem espera tem de ser acordado pela devolução");
        assertSame(a, recebida.get());
        assertEquals(1, f.criadas.get());
    }

    // ---------- maxLifetime ----------

    @Test void maxLifetimeDescartaAoEmprestarNaFronteira() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(2, 100, 0, f, t);
        Conn a = p.emprestar(0);
        t.em(50);
        p.devolver(a);
        t.em(99);
        assertSame(a, p.emprestar(0), "99 < 100: ainda vale");
        p.devolver(a);
        t.em(100);
        Conn b = p.emprestar(0);
        assertNotSame(a, b, "100 >= 100: venceu");
        assertEquals(List.of(a), f.fechadas);
        assertEquals(1, p.descartadasNoTotal());
        assertEquals(2, p.criadasNoTotal());
    }

    @Test void conexaoVencidaNaoVoltaAoPool() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(2, 100, 0, f, t);
        Conn a = p.emprestar(0);
        t.em(150);
        p.devolver(a);
        assertEquals(0, p.ociosas());
        assertEquals(0, p.abertas());
        assertEquals(List.of(a), f.fechadas);
    }

    @Test void vidaContaDaCriacaoENaoDoUltimoUso() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(1, 100, 0, f, t);
        Conn a = p.emprestar(0);
        t.em(90);
        p.devolver(a);
        t.em(100);
        Conn b = p.emprestar(0);
        assertNotSame(a, b, "devolver aos 90 não renova a vida");
    }

    // ---------- idleTimeout ----------

    @Test void idleTimeoutContaDaUltimaDevolucao() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(2, 0, 30, f, t);
        Conn a = p.emprestar(0);
        t.em(10);
        p.devolver(a);
        t.em(39);
        assertSame(a, p.emprestar(0), "29 ms ociosa: vale");
        p.devolver(a);
        t.em(69);
        Conn b = p.emprestar(0);
        assertNotSame(a, b, "30 ms ociosa desde a última devolução: venceu");
        assertEquals(List.of(a), f.fechadas);
    }

    @Test void zeroDesligaOsLimites() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(1, 0, 0, f, t);
        Conn a = p.emprestar(0);
        p.devolver(a);
        t.em(Long.MAX_VALUE / 2);
        assertSame(a, p.emprestar(0));
        assertTrue(f.fechadas.isEmpty());
    }

    @Test void emprestarFechaAsVencidasDoTopoAteAcharUmaValida() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(3, 100, 0, f, t);
        Conn x = p.emprestar(0);          // criada em 0
        t.em(50);
        Conn y = p.emprestar(0);          // criada em 50
        t.em(60);
        p.devolver(y);
        t.em(70);
        p.devolver(x);                    // x no topo da fila (LIFO)
        t.em(100);                        // x viveu 100 (venceu); y viveu 50 (vale)
        assertSame(y, p.emprestar(0));
        assertEquals(List.of(x), f.fechadas);
        assertEquals(1, p.abertas());
    }

    @Test void ociosaVencidaAtrasDaValidaSoSaiNaPoda() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(3, 0, 50, f, t);
        Conn a = p.emprestar(0);
        Conn b = p.emprestar(0);
        p.devolver(a);
        t.em(60);
        p.devolver(b);                    // b no topo
        t.em(80);                         // a ociosa há 80 (vencida); b há 20 (vale)
        assertSame(b, p.emprestar(0), "o topo vale: é entregue sem olhar o resto");
        assertEquals(1, p.ociosas());
        assertEquals(1, p.podarOciosas(), "a poda fecha a vencida que ficou para trás");
        assertEquals(List.of(a), f.fechadas);
    }

    @Test void vencidaLiberaVagaParaCriarUmaNova() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(1, 0, 10, f, t);
        Conn a = p.emprestar(0);
        p.devolver(a);
        t.em(10);
        Conn b = p.emprestar(0);      // a vence; a vaga é reaproveitada para criar b
        assertNotSame(a, b);
        assertEquals(1, p.abertas());
    }

    // ---------- poda ----------

    @Test void podarFechaSoAsOciosasVencidas() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(4, 0, 50, f, t);
        Conn a = p.emprestar(0);
        Conn b = p.emprestar(0);
        Conn emUso = p.emprestar(0);
        p.devolver(a);
        t.em(30);
        p.devolver(b);
        t.em(60);               // a ociosa há 60 (vence), b há 30 (vale), emUso nunca é tocada
        assertEquals(1, p.podarOciosas());
        assertEquals(List.of(a), f.fechadas);
        assertEquals(1, p.ociosas());
        assertEquals(1, p.emUso());
        assertEquals(0, p.podarOciosas(), "nada mais vencido");
        assertNotNull(emUso);
    }

    @Test void podaLiberaVagaParaQuemEspera() throws Exception {
        Fabrica f = new Fabrica();
        Relogio t = new Relogio();
        Solution.Pool<Conn> p = pool(1, 100, 0, f, t);
        Conn a = p.emprestar(0);
        p.devolver(a);
        t.em(100);
        assertEquals(1, p.podarOciosas());
        assertEquals(0, p.abertas());
        assertNotNull(p.emprestar(0));
    }

    // ---------- devoluções e erros ----------

    @Test void devolverDuasVezesLanca() throws Exception {
        Solution.Pool<Conn> p = pool(2, 0, 0, new Fabrica(), new Relogio());
        Conn a = p.emprestar(0);
        p.devolver(a);
        assertThrows(IllegalStateException.class, () -> p.devolver(a));
    }

    @Test void devolverDesconhecidaLanca() {
        Solution.Pool<Conn> p = pool(2, 0, 0, new Fabrica(), new Relogio());
        assertThrows(IllegalArgumentException.class, () -> p.devolver(new Conn(99)));
    }

    @Test void falhaNaCriacaoNaoConsomeVaga() throws Exception {
        Relogio t = new Relogio();
        AtomicInteger chamadas = new AtomicInteger();
        Solution.Pool<Conn> p = new Solution.Pool<>(1, 0, 0, () -> {
            if (chamadas.incrementAndGet() == 1) throw new IllegalStateException("banco fora do ar");
            return new Conn(chamadas.get());
        }, c -> {}, t);
        assertThrows(IllegalStateException.class, () -> p.emprestar(0));
        assertEquals(0, p.abertas());
        assertEquals(0, p.criadasNoTotal());
        assertNotNull(p.emprestar(0), "a vaga continua livre");
    }

    @Test void argumentosInvalidos() {
        Relogio t = new Relogio();
        Fabrica f = new Fabrica();
        assertThrows(IllegalArgumentException.class, () -> pool(0, 0, 0, f, t));
        assertThrows(IllegalArgumentException.class, () -> pool(1, -1, 0, f, t));
        assertThrows(IllegalArgumentException.class, () -> pool(1, 0, -1, f, t));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Pool<Conn>(1, 0, 0, null, f::fechar, t));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Pool<Conn>(1, 0, 0, f::criar, null, t));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Pool<Conn>(1, 0, 0, f::criar, f::fechar, null));
        Solution.Pool<Conn> p = pool(1, 0, 0, f, t);
        assertThrows(IllegalArgumentException.class, () -> p.emprestar(-1));
    }

    // ---------- concorrência ----------

    @Test void limiteRespeitadoComVariasThreads() throws Exception {
        final int max = 4, threads = 16, voltas = 300;
        Fabrica f = new Fabrica();
        Solution.Pool<Conn> p = pool(max, 0, 0, f, new Relogio());
        AtomicInteger emUsoAgora = new AtomicInteger();
        AtomicInteger pico = new AtomicInteger();
        AtomicInteger excecoes = new AtomicInteger();
        CountDownLatch largada = new CountDownLatch(1);
        CountDownLatch fim = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                try {
                    largada.await();
                    for (int v = 0; v < voltas; v++) {
                        Conn c = p.emprestar(5000);
                        int agora = emUsoAgora.incrementAndGet();
                        pico.accumulateAndGet(agora, Math::max);
                        Thread.yield();
                        emUsoAgora.decrementAndGet();
                        p.devolver(c);
                    }
                } catch (Throwable e) {
                    excecoes.incrementAndGet();
                } finally {
                    fim.countDown();
                }
            }).start();
        }
        largada.countDown();
        assertTrue(fim.await(20, TimeUnit.SECONDS), "as threads terminam (sem deadlock)");
        assertEquals(0, excecoes.get(), "nenhum timeout nem erro");
        assertTrue(pico.get() <= max, "no máximo " + max + " em uso ao mesmo tempo, mas o pico foi " + pico.get());
        assertTrue(f.criadas.get() <= max, "nunca mais que " + max + " conexões criadas, mas foram " + f.criadas.get());
        assertEquals(0, p.emUso());
        assertEquals(p.abertas(), p.ociosas());
        assertEquals(0, f.fechadas.size());
    }
}
